import { cacheLife, cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: number
}

const posts: Post[] = [
  {
    id: '1',
    title: 'Welcome to the blog',
    content: 'This is the first post.',
    createdAt: Date.now(),
  },
]

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheLife('hours')
  cacheTag('posts')
  return posts
}

export function addPost(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: Date.now(),
  }
  posts.unshift(post)
  return post
}

